6	import React, { useState, useCallback, useRef } from 'react';
7	import { useDrawingChallenge } from '../../../hooks/useDrawingChallenge';
8	import GameLayout from '../../shared/GameLayout';
9	import DrawingCanvasWithTools from '../../Canvas/DrawingCanvasWithTools';
10	import type { Category, GameMode } from './types';
11	import { categoryNames } from './prompts';
12	import { formatTime } from '../../../utils/gameUtils';
13	
14	interface DrawingChallengePageProps {
15	  onNavigateHome: () => void;
16	}
17	
18	const DrawingChallengePage: React.FC<DrawingChallengePageProps> = ({ onNavigateHome }) => {
19	  const {
20	    gameState,
21	    startChallenge,
22	    finishChallenge,
23	    nextPrompt,
24	    setCategory,
25	    setMode,
26	    setTimeLimit
27	  } = useDrawingChallenge();
28	
29	  const {
30	    currentPrompt,
31	    gameStatus,
32	    mode,
33	    category,
34	    timeLimit,
35	    timeRemaining,
36	    completedChallenges
37	  } = gameState;
38	
39	  const [showCanvas, setShowCanvas] = useState(false);
40	  const clearCanvasRef = useRef<(() => void) | null>(null);
41	
42	  const handleStartDrawing = useCallback(() => {
43	    startChallenge();
44	    setShowCanvas(true);
45	  }, [startChallenge]);
46	
47	  const handleFinish = useCallback(() => {
48	    finishChallenge();
49	    setShowCanvas(false);
50	  }, [finishChallenge]);
51	
52	  const handleNextPrompt = useCallback(() => {
53	    nextPrompt();
54	    setShowCanvas(false);
55	    if (clearCanvasRef.current) {
56	      clearCanvasRef.current();
57	    }
58	  }, [nextPrompt]);
59	
60	  const handleCategoryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
61	    setCategory(e.target.value as Category);
62	    setShowCanvas(false);
63	  };
64	
65	  const handleModeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
66	    setMode(e.target.value as GameMode);
67	    setShowCanvas(false);
68	  };
69	
70	  const handleTimeLimitChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
71	    setTimeLimit(parseInt(e.target.value, 10));
72	  };
73	
74	  const handleClearCanvas = useCallback(() => {
75	    if (clearCanvasRef.current) {
76	      clearCanvasRef.current();
77	    }
78	  }, []);
79	
80	  const headerActions = (
81	    <>
82	      {/* Category Selector - Compact on mobile */}
83	      <select
84	        value={category}
85	        onChange={handleCategoryChange}
86	        disabled={gameStatus === 'drawing'}
87	        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
88	        title="Drawing Category"
89	      >
90	        {Object.entries(categoryNames).map(([key, name]) => (
91	          <option key={key} value={key}>
92	            {name}
93	          </option>
94	        ))}
95	      </select>
96	
97	      {/* Mode Selector - Compact on mobile */}
98	      <select
99	        value={mode}
100	        onChange={handleModeChange}
101	        disabled={gameStatus === 'drawing'}
102	        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
103	        title="Game Mode"
104	      >
105	        <option value="free">✨ Free</option>
106	        <option value="timed">⏱️ Timed</option>
107	      </select>
108	
109	      {/* Time Limit Selector (only in timed mode) - Compact on mobile */}
110	      {mode === 'timed' && (
111	        <select
112	          value={timeLimit}
113	          onChange={handleTimeLimitChange}
114	          disabled={gameStatus === 'drawing'}
115	          className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
116	          title="Time Limit"
117	        >
118	          <option value={60}>1m</option>
119	          <option value={120}>2m</option>
120	          <option value={180}>3m</option>
121	          <option value={300}>5m</option>
122	        </select>
123	      )}
124	    </>
125	  );
126	
127	  return (
128	    <GameLayout
129	      title="Drawing Challenge"
130	      emoji="🎨"
131	      onNavigateHome={onNavigateHome}
132	      headerActions={headerActions}
