13	interface UsePopBalloonsReturn {
14	  gameState: PopBalloonsState;
15	  handleBalloonPop: (balloonId: string) => void;
16	  startGame: () => void;
17	  resetGame: () => void;
18	  setDifficulty: (difficulty: Difficulty) => void;
