22	export const usePopBalloons = (): UsePopBalloonsReturn => {
23	  const [difficulty, setDifficultyState] = useState<Difficulty>('easy');
24	  const [gridSize, setGridSizeState] = useState<GridSize>('small');
25	  const [balloons, setBalloons] = useState<Balloon[]>([]);
26	  const [score, setScore] = useState(0);
27	  const [highScore, setHighScore] = useState(0);
28	  const [combo, setCombo] = useState(0);
29	  const [maxCombo, setMaxCombo] = useState(0);
30	  const [gameStatus, setGameStatus] = useState<GameStatus>('ready');
31	  const [timeRemaining, setTimeRemaining] = useState(difficultySettings[difficulty].gameDuration);
32	  const [lives, setLives] = useState(difficultySettings[difficulty].startingLives);
33	  const [totalPopped, setTotalPopped] = useState(0);
34	  const [totalMissed, setTotalMissed] = useState(0);
35	
36	  const spawnTimerRef = useRef<NodeJS.Timeout | null>(null);
37	  const gameTimerRef = useRef<NodeJS.Timeout | null>(null);
38	  const lastPopTimeRef = useRef<number>(0);
39	  const occupiedPositionsRef = useRef<Set<string>>(new Set());
40	
41	  // Load high score
42	  useEffect(() => {
43	    const savedHighScore = getHighScore(`${GAME_KEY}_${difficulty}`);
44	    setHighScore(savedHighScore);
45	  }, [difficulty]);
46	
47	  // Initialize game
48	  const initializeGame = useCallback(() => {
49	    const settings = difficultySettings[difficulty];
50	    setBalloons([]);
51	    setScore(0);
52	    setCombo(0);
53	    setMaxCombo(0);
54	    setTimeRemaining(settings.gameDuration);
55	    setLives(settings.startingLives);
56	    setTotalPopped(0);
57	    setTotalMissed(0);
58	    setGameStatus('ready');
59	    occupiedPositionsRef.current.clear();
60	    lastPopTimeRef.current = 0;
61	  }, [difficulty]);
62	
63	  // Get random unoccupied position
64	  const getRandomPosition = useCallback((): { row: number; col: number } | null => {
65	    const available: { row: number; col: number }[] = [];
66	    const currentGridSize = gridSizeSettings[gridSize].size;
67	
68	    for (let row = 0; row < currentGridSize; row++) {
69	      for (let col = 0; col < currentGridSize; col++) {
70	        const key = `${row}-${col}`;
71	        if (!occupiedPositionsRef.current.has(key)) {
72	          available.push({ row, col });
73	        }
74	      }
75	    }
76	
77	    if (available.length === 0) return null;
78	    return randomChoice(available);
79	  }, [gridSize]);
80	
81	  // Determine balloon type based on difficulty
82	  const getBalloonType = useCallback((): BalloonType => {
83	    const settings = difficultySettings[difficulty];
84	    const rand = Math.random();
85	
86	    if (rand < settings.bombChance) {
87	      return 'bomb';
88	    } else if (rand < settings.bombChance + settings.goldenChance) {
89	      return 'golden';
90	    }
91	    return 'normal';
92	  }, [difficulty]);
93	
94	  // Spawn a new balloon
95	  const spawnBalloon = useCallback(() => {
96	    const position = getRandomPosition();
97	    if (!position) return; // Grid is full
98	
99	    const settings = difficultySettings[difficulty];
100	    const type = getBalloonType();
101	
102	    const balloon: Balloon = {
103	      id: `balloon-${Date.now()}-${Math.random()}`,
104	      position,
105	      type,
106	      color: type === 'golden' ? 'hsl(45, 100%, 60%)' : type === 'bomb' ? 'hsl(0, 0%, 30%)' : randomChoice(balloonColors),
107	      lifetime: settings.balloonLifetime,
108	      spawnTime: Date.now()
109	    };
110	
111	    const posKey = `${position.row}-${position.col}`;
112	    occupiedPositionsRef.current.add(posKey);
113	
114	    setBalloons(prev => [...prev, balloon]);
115	
116	    // Auto-remove balloon after lifetime
117	    setTimeout(() => {
118	      setBalloons(prev => {
