/**
 * useBubblePop rAF loop tests (PR-4c2)
 *
 * Validates that the animation loop:
 *  - fires exactly ONE setGameState per rAF frame (~60/s, not ~120/s)
 *  - is set up ONCE and never restarted when bubble count changes
 *  - halts correctly on pause and resumes on unpause
 */

import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { useBubblePop } from './useBubblePop';

// ── Setup ─────────────────────────────────────────────────────────────────────

beforeEach(() => {
  vi.useFakeTimers();
});

afterEach(() => {
  vi.useRealTimers();
});

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Wraps global.requestAnimationFrame with a counter, returns cleanup fn. */
function countRaf(): { getCount: () => number; restore: () => void } {
  let count = 0;
  const original = global.requestAnimationFrame;
  global.requestAnimationFrame = (fn: FrameRequestCallback): number => {
    count++;
    return original(fn);
  };
  return {
    getCount: () => count,
    restore: () => { global.requestAnimationFrame = original; },
  };
}

// ── Tests ─────────────────────────────────────────────────────────────────────

describe('useBubblePop initialisation', () => {
  it('starts with correct default state', () => {
    const { result } = renderHook(() => useBubblePop());

    expect(result.current.gameState.score).toBe(0);
    expect(result.current.gameState.bubblesPopped).toBe(0);
    expect(result.current.gameState.gameStatus).toBe('playing');
    expect(Array.isArray(result.current.gameState.bubbles)).toBe(true);
  });
});

describe('useBubblePop — rAF loop (PR-4c2)', () => {
  it('registers ~60 rAF callbacks in 1 second of game time', () => {
    // Each rAF callback dispatches ONE setGameState (merged spawn+move update).
    // Counts rAF invocations, which equals the number of state updates per second.
    const raf = countRaf();

    const { unmount } = renderHook(() => useBubblePop());
    raf.restore(); // swap the counting wrapper in AFTER initial rAF registration

    // Fresh counter from here (don't count the setup call)
    const raf2 = countRaf();

    act(() => {
      vi.advanceTimersByTime(1000);
    });

    // jsdom rAF ≈ setTimeout(fn, 1000/60) → ~60 frames per second
    const frames = raf2.getCount();
    expect(frames).toBeGreaterThanOrEqual(50);
    expect(frames).toBeLessThanOrEqual(70);

    raf2.restore();
    unmount();
  });

  it('does NOT cancel/restart the rAF loop when bubbles spawn', () => {
    // KEY TEST: with the old dep array [gameStatus, bubbles.length, createBubble],
    // every bubble spawn changes bubbles.length → effect cleanup fires →
    // cancelAnimationFrame called → loop restarted. Fixed dep array prevents this.
    const cancelSpy = vi.spyOn(window, 'cancelAnimationFrame');

    const { unmount } = renderHook(() => useBubblePop());
    cancelSpy.mockClear(); // clear any calls from initial effect setup

    // Advance past the 2-second spawn threshold so at least one bubble spawns
    act(() => {
      vi.advanceTimersByTime(2100);
    });

    // cancelAnimationFrame must NOT have been called during gameplay —
    // the loop should be running continuously without restarts.
    expect(cancelSpy).not.toHaveBeenCalled();

    unmount();
    cancelSpy.mockRestore();
  });

  it('game status stays playing after 1 second of animation', () => {
    const { result, unmount } = renderHook(() => useBubblePop());

    act(() => {
      vi.advanceTimersByTime(1000);
    });

    expect(result.current.gameState.gameStatus).toBe('playing');
    unmount();
  });

  it('score remains 0 after 1 second (no auto-pops)', () => {
    const { result, unmount } = renderHook(() => useBubblePop());

    act(() => {
      vi.advanceTimersByTime(1000);
    });

    expect(result.current.gameState.score).toBe(0);
    expect(result.current.gameState.bubblesPopped).toBe(0);
    unmount();
  });
});

describe('useBubblePop — pause/resume', () => {
  it('pausing cancels the rAF loop (cancelAnimationFrame called once)', () => {
    const cancelSpy = vi.spyOn(window, 'cancelAnimationFrame');

    const { result, unmount } = renderHook(() => useBubblePop());
    cancelSpy.mockClear(); // ignore mount-time setup

    act(() => {
      result.current.togglePause();
    });

    // Effect cleanup fires exactly once when gameStatus transitions playing→paused
    expect(cancelSpy).toHaveBeenCalledTimes(1);

    expect(result.current.gameState.gameStatus).toBe('paused');

    unmount();
    cancelSpy.mockRestore();
  });

  it('paused game does not register rAF callbacks', () => {
    const { result, unmount } = renderHook(() => useBubblePop());

    act(() => { result.current.togglePause(); });

    const raf = countRaf();

    act(() => {
      vi.advanceTimersByTime(1000); // advance while paused
    });

    expect(raf.getCount()).toBe(0);
    raf.restore();
    unmount();
  });

  it('resuming after pause restarts the rAF loop', () => {
    const { result, unmount } = renderHook(() => useBubblePop());

    // Pause then resume
    act(() => { result.current.togglePause(); });
    act(() => { result.current.togglePause(); });

    expect(result.current.gameState.gameStatus).toBe('playing');

    const raf = countRaf();
    act(() => { vi.advanceTimersByTime(500); });

    // ~30 frames in 500ms — confirms the loop is running again
    expect(raf.getCount()).toBeGreaterThanOrEqual(20);
    raf.restore();
    unmount();
  });
});

describe('useBubblePop — reset', () => {
  it('resetGame restores initial state', () => {
    const { result, unmount } = renderHook(() => useBubblePop());

    act(() => { result.current.resetGame(); });

    expect(result.current.gameState.score).toBe(0);
    expect(result.current.gameState.bubblesPopped).toBe(0);
    expect(result.current.gameState.gameStatus).toBe('playing');

    unmount();
  });
});

describe('useBubblePop — pop animation timeout (PR-4c3)', () => {
  it('marks a popped bubble as popping immediately', () => {
    const { result, unmount } = renderHook(() => useBubblePop());

    act(() => { vi.advanceTimersByTime(2100); }); // trigger natural spawn
    const bubbles = result.current.gameState.bubbles;
    if (bubbles.length === 0) { unmount(); return; }

    const bubbleId = bubbles[0].id;
    act(() => { result.current.popBubble(bubbleId); });

    expect(result.current.gameState.bubbles.find(b => b.id === bubbleId)?.popping).toBe(true);
    unmount();
  });

  it('removes the popped bubble from list after 500ms animation delay', () => {
    const { result, unmount } = renderHook(() => useBubblePop());

    act(() => { vi.advanceTimersByTime(2100); });
    const bubbles = result.current.gameState.bubbles;
    if (bubbles.length === 0) { unmount(); return; }

    const bubbleId = bubbles[0].id;
    act(() => { result.current.popBubble(bubbleId); });

    // Still in the list (marked popping) right after pop
    expect(result.current.gameState.bubbles.find(b => b.id === bubbleId)).toBeDefined();

    // After 500ms the animation timeout fires and removes the bubble
    act(() => { vi.advanceTimersByTime(500); });
    expect(result.current.gameState.bubbles.find(b => b.id === bubbleId)).toBeUndefined();

    unmount();
  });

  it('pop animation timeout is cancelled on unmount — no stale setState leak', () => {
    // BUG: the 500ms pop-cleanup setTimeout was untracked, leaking on unmount.
    // FIX: ID pushed to popTimeoutsRef, cleared in cleanup useEffect.
    const clearTimeoutSpy = vi.spyOn(global, 'clearTimeout');

    const { result, unmount } = renderHook(() => useBubblePop());
    act(() => { vi.advanceTimersByTime(2100); });
    const bubbles = result.current.gameState.bubbles;
    if (bubbles.length === 0) { unmount(); clearTimeoutSpy.mockRestore(); return; }

    const bubbleId = bubbles[0].id;
    act(() => { result.current.popBubble(bubbleId); });

    clearTimeoutSpy.mockClear(); // count only calls from the unmount cleanup

    unmount();

    // Fixed: clearTimeout called for the pop animation timeout (plus rAF cancel)
    // — at least 1 pop-specific clearTimeout call
    expect(clearTimeoutSpy.mock.calls.length).toBeGreaterThanOrEqual(1);

    // Advancing past 500ms must not throw (timeout was cleared)
    expect(() => {
      act(() => { vi.advanceTimersByTime(500); });
    }).not.toThrow();

    clearTimeoutSpy.mockRestore();
  });
});

/**
 * useSimonSays tests (PR-4c3)
 *
 * Covers:
 *  - forEach cancellation bug: all steps of a multi-step sequence now show
 *  - all 3 levels of nested timeouts cleared on unmount / resetGame
 */

import { renderHook, act } from '@testing-library/react';
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { useSimonSays } from './useSimonSays';

// ── jsdom stubs ───────────────────────────────────────────────────────────────

// AudioContext is not available in jsdom — stub it before any hook renders
const mockOscillator = {
  connect: vi.fn(),
  start: vi.fn(),
  stop: vi.fn(),
  frequency: { value: 0 },
  type: 'sine' as OscillatorType,
};
const mockGainNode = { connect: vi.fn(), gain: { value: 0 } };
const mockAudioCtx = {
  createOscillator: () => mockOscillator,
  createGain: () => mockGainNode,
  destination: {},
  currentTime: 0,
  close: vi.fn().mockResolvedValue(undefined),
};
vi.stubGlobal('AudioContext', vi.fn(() => mockAudioCtx));

// Mock gameUtils side-effects so they don't throw
vi.mock('../utils/gameUtils', () => ({
  playSound: vi.fn(),
  getHighScore: vi.fn(() => 0),
  saveHighScore: vi.fn(),
}));

// ── Setup ─────────────────────────────────────────────────────────────────────

beforeEach(() => { vi.useFakeTimers(); });
afterEach(() => { vi.useRealTimers(); });

// ── Tests ─────────────────────────────────────────────────────────────────────

describe('useSimonSays — initialisation', () => {
  it('starts in ready state with empty sequence', () => {
    const { result } = renderHook(() => useSimonSays());

    expect(result.current.gameState.gameStatus).toBe('ready');
    expect(result.current.gameState.sequence).toHaveLength(0);
    expect(result.current.gameState.round).toBe(0);
    expect(result.current.gameState.showingIndex).toBe(-1);
  });
});

describe('useSimonSays — sequence display', () => {
  it('round 1 shows sequence and transitions to playing', () => {
    const { result, unmount } = renderHook(() => useSimonSays());

    act(() => { result.current.startGame(); });
    expect(result.current.gameState.gameStatus).toBe('showing');
    expect(result.current.gameState.sequence).toHaveLength(1);

    // normal speed: delay=600; sequence length=1 → transitions at delay*0.6+200=560ms
    act(() => { vi.advanceTimersByTime(700); });

    expect(result.current.gameState.gameStatus).toBe('playing');
    unmount();
  });

  it('shows first button immediately at round start (showingIndex != -1)', () => {
    const { result, unmount } = renderHook(() => useSimonSays());

    act(() => { result.current.startGame(); });

    // Advance 1ms: level-1 timeout (delay = idx*600 = 0) fires → highlights button
    act(() => { vi.advanceTimersByTime(1); });

    // First button should be highlighted
    expect(result.current.gameState.showingIndex).not.toBe(-1);

    unmount();
  });

  it('shows ALL buttons in a 2-step sequence — forEach cancellation bug fixed', () => {
    // BUG: old forEach overwrote showTimeoutRef on every iteration and called
    // clearTimeout on the previous, cancelling every step except the last.
    // FIX: all outer + inner timeout IDs tracked in an array; no cancellation.
    const { result, unmount } = renderHook(() => useSimonSays());

    // Complete round 1
    act(() => { result.current.startGame(); });
    act(() => { vi.advanceTimersByTime(700); }); // past 560ms transition
    expect(result.current.gameState.gameStatus).toBe('playing');

    // Press the one correct button to move to round 2
    const correctBtn = result.current.gameState.sequence[0];
    act(() => { result.current.handleButtonPress(correctBtn); });

    // Advance 1200ms:
    //   – 1000ms: round-transition setTimeout fires → showSequence([btn0, btn1])
    //   – +0ms:   level-1 for idx=0 fires (delay=0) → showingIndex = btn0
    //   – level-1 for idx=1 (delay=600) and subsequent dims haven't fired yet
    act(() => { vi.advanceTimersByTime(1200); });

    // Fixed: step-0 highlighted (showingIndex = btn0, which is 0..3)
    // Buggy: step-0 was cancelled → showingIndex stays -1
    expect(result.current.gameState.showingIndex).not.toBe(-1);

    unmount();
  });
});

describe('useSimonSays — timeout cleanup', () => {
  it('clears all nested timeouts (including level-2) when unmounted mid-sequence', () => {
    // BUG: only outermost ID was in showTimeoutRef; inner timeouts leaked.
    // FIX: showTimeoutsRef is an array; cleanup clears every tracked ID.
    const clearTimeoutSpy = vi.spyOn(global, 'clearTimeout');

    const { result, unmount } = renderHook(() => useSimonSays());
    act(() => { result.current.startGame(); });

    // Fire level-1 (delay=0): it pushes the level-2 ID into showTimeoutsRef
    act(() => { vi.advanceTimersByTime(1); });

    clearTimeoutSpy.mockClear(); // only count calls produced by unmount

    unmount();

    // Fixed: clearTimeout called for level-1 ID (already fired, no-op) AND
    // level-2 ID (still pending) = 2 calls minimum.
    // Buggy: only 1 call (the single outer ID stored in showTimeoutRef).
    expect(clearTimeoutSpy.mock.calls.length).toBeGreaterThanOrEqual(2);

    clearTimeoutSpy.mockRestore();
  });

  it('resetGame clears all pending sequence timeouts', () => {
    const clearTimeoutSpy = vi.spyOn(global, 'clearTimeout');

    const { result, unmount } = renderHook(() => useSimonSays());
    act(() => { result.current.startGame(); });
    act(() => { vi.advanceTimersByTime(1); }); // fire level-1, level-2 now pending

    clearTimeoutSpy.mockClear();
    act(() => { result.current.resetGame(); });

    // resetGame should clear all tracked timeouts
    expect(clearTimeoutSpy.mock.calls.length).toBeGreaterThanOrEqual(2);
    expect(result.current.gameState.gameStatus).toBe('ready');

    clearTimeoutSpy.mockRestore();
    unmount();
  });

  it('does not throw when unmounted during a sequence', () => {
    const { result, unmount } = renderHook(() => useSimonSays());
    act(() => { result.current.startGame(); });

    // Unmount mid-sequence; advancing time afterwards must not crash
    unmount();

    expect(() => {
      act(() => { vi.advanceTimersByTime(5000); });
    }).not.toThrow();
  });
});

/**
 * Bubble Pop Game Hook
 * Simple relaxing bubble popping game
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import type { BubblePopState, Bubble } from '../components/Games/BubblePop/types';
import { playSound } from '../utils/gameUtils';

const BUBBLE_COLORS = ['#FF6B9D', '#C44569', '#4ECDC4', '#44A08D', '#F7DC6F', '#BB8FCE', '#85C1E2', '#F8B195'];

export const useBubblePop = () => {
  const [gameState, setGameState] = useState<BubblePopState>({
    bubbles: [],
    score: 0,
    bubblesPopped: 0,
    gameStatus: 'playing'
  });

  const animationFrameRef = useRef<number>();
  const lastBubbleTimeRef = useRef<number>(Date.now());
  // Tracks pending pop-animation timeouts so they can be cleared on unmount
  const popTimeoutsRef = useRef<NodeJS.Timeout[]>([]);

  // Generate random bubble
  const createBubble = useCallback((): Bubble => {
    const size = 40 + Math.random() * 40;
    return {
      id: `bubble-${Date.now()}-${Math.random()}`,
      x: Math.random() * (window.innerWidth - size),
      y: window.innerHeight + size,
      size,
      color: BUBBLE_COLORS[Math.floor(Math.random() * BUBBLE_COLORS.length)],
      speed: 0.5 + Math.random() * 1.5
    };
  }, []);

  // Pop bubble
  const popBubble = useCallback((bubbleId: string) => {
    setGameState(prev => {
      const bubble = prev.bubbles.find(b => b.id === bubbleId);
      if (!bubble || bubble.popping) return prev;

      playSound('pop');

      // Mark bubble as popping
      const updatedBubbles = prev.bubbles.map(b =>
        b.id === bubbleId ? { ...b, popping: true } : b
      );

      // Remove bubble after animation completes (500ms); tracked for cleanup
      const popId = setTimeout(() => {
        setGameState(current => ({
          ...current,
          bubbles: current.bubbles.filter(b => b.id !== bubbleId)
        }));
      }, 500);
      popTimeoutsRef.current.push(popId);

      return {
        ...prev,
        bubbles: updatedBubbles,
        score: prev.score + Math.floor(bubble.size / 10),
        bubblesPopped: prev.bubblesPopped + 1
      };
    });
  }, []);

  // Animation loop — stable: deps contain only gameStatus so the loop is set up
  // once per play/pause transition and never restarted on bubble count changes.
  useEffect(() => {
    if (gameState.gameStatus !== 'playing') return;

    const animate = () => {
      const now = Date.now();

      // ONE setGameState per frame: spawn (if due) + move + filter in a single
      // functional update so the second operation reads post-spawn state via
      // `prev`, never a stale closure value.
      setGameState(prev => {
        // Check cap against prev.bubbles.length, not stale closure
        let bubbles = prev.bubbles;
        if (now - lastBubbleTimeRef.current > 2000 && bubbles.length < 12) {
          lastBubbleTimeRef.current = now;
          bubbles = [...bubbles, createBubble()];
        }

        bubbles = bubbles
          .map(bubble => ({ ...bubble, y: bubble.y - bubble.speed }))
          .filter(bubble => bubble.y > -bubble.size);

        return { ...prev, bubbles };
      });

      animationFrameRef.current = requestAnimationFrame(animate);
    };

    animationFrameRef.current = requestAnimationFrame(animate);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  // gameState.bubbles.length intentionally omitted — read from prev inside the
  // functional update instead of the closure to avoid loop restarts on every spawn.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [gameState.gameStatus, createBubble]);

  // Clear all pending pop-animation timeouts on unmount
  useEffect(() => {
    return () => {
      popTimeoutsRef.current.forEach(clearTimeout);
      popTimeoutsRef.current = [];
    };
  }, []);

  const togglePause = useCallback(() => {
    setGameState(prev => ({
      ...prev,
      gameStatus: prev.gameStatus === 'playing' ? 'paused' : 'playing'
    }));
  }, []);

  const resetGame = useCallback(() => {
    setGameState({
      bubbles: [],
      score: 0,
      bubblesPopped: 0,
      gameStatus: 'playing'
    });
    lastBubbleTimeRef.current = Date.now();
  }, []);

  return {
    gameState,
    popBubble,
    togglePause,
    resetGame
  };
};

/**
 * Simon Says Game Hook
 * Manages game state and logic for Simon Says pattern memory game
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import type { SimonSaysState, Speed } from '../components/Games/SimonSays/types';
import { playSound, getHighScore, saveHighScore } from '../utils/gameUtils';

const SPEED_DELAYS = {
  slow: 800,
  normal: 600,
  fast: 400
};

export const useSimonSays = () => {
  const [gameState, setGameState] = useState<SimonSaysState>({
    sequence: [],
    userInput: [],
    round: 0,
    gameStatus: 'ready',
    speed: 'normal',
    highScore: getHighScore('simonSays'),
    showingIndex: -1
  });

  const audioContextRef = useRef<AudioContext | null>(null);
  // Array tracks ALL pending timeout IDs across all 3 nesting levels so every
  // one can be cleared on reset or unmount (the single-ref approach only tracked
  // the last outer timeout and leaked the inner ones).
  const showTimeoutsRef = useRef<NodeJS.Timeout[]>([]);

  // Initialize audio context
  useEffect(() => {
    const AudioContextClass = window.AudioContext || (window as Window & typeof globalThis & { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    audioContextRef.current = new AudioContextClass();
    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, []);

  // Play button tone
  const playButtonTone = useCallback((buttonIndex: number) => {
    const frequencies = [261.63, 329.63, 392.00, 523.25]; // C, E, G, C
    const frequency = frequencies[buttonIndex];

    if (audioContextRef.current) {
      const oscillator = audioContextRef.current.createOscillator();
      const gainNode = audioContextRef.current.createGain();

      oscillator.connect(gainNode);
      gainNode.connect(audioContextRef.current.destination);

      oscillator.frequency.value = frequency;
      oscillator.type = 'sine';
      gainNode.gain.value = 0.3;

      oscillator.start();
      oscillator.stop(audioContextRef.current.currentTime + 0.3);
    }
  }, []);

  // Show sequence to player
  const showSequence = useCallback((sequence: number[]) => {
    // Cancel any in-flight timeouts from a previous showSequence call
    showTimeoutsRef.current.forEach(clearTimeout);
    showTimeoutsRef.current = [];

    setGameState(prev => ({ ...prev, gameStatus: 'showing', showingIndex: -1 }));

    const delay = SPEED_DELAYS[gameState.speed];

    sequence.forEach((buttonIndex, idx) => {
      // LEVEL 1: highlight each button in turn
      const outerId = setTimeout(() => {
        setGameState(prev => ({ ...prev, showingIndex: buttonIndex }));
        playButtonTone(buttonIndex);

        // LEVEL 2: un-highlight after a short flash
        const innerId = setTimeout(() => {
          setGameState(prev => ({ ...prev, showingIndex: -1 }));

          // LEVEL 3: transition to 'playing' after the last button
          if (idx === sequence.length - 1) {
            const finalId = setTimeout(() => {
              setGameState(prev => ({ ...prev, gameStatus: 'playing' }));
            }, 200);
            showTimeoutsRef.current.push(finalId);
          }
        }, delay * 0.6);
        showTimeoutsRef.current.push(innerId);
      }, idx * delay);

      // Track the outer ID (do NOT clear the previous iteration's timeout —
      // the old code had a forEach bug that cancelled every step except the last)
      showTimeoutsRef.current.push(outerId);
    });
  }, [gameState.speed, playButtonTone]);

  // Start new game
  const startGame = useCallback(() => {
    const firstButton = Math.floor(Math.random() * 4);
    const newSequence = [firstButton];

    setGameState(prev => ({
      ...prev,
      sequence: newSequence,
      userInput: [],
      round: 1,
      gameStatus: 'showing',
      showingIndex: -1
    }));

    showSequence(newSequence);
  }, [showSequence]);

  // Handle button press
  const handleButtonPress = useCallback((buttonIndex: number) => {
    if (gameState.gameStatus !== 'playing') return;

    playButtonTone(buttonIndex);

    const newUserInput = [...gameState.userInput, buttonIndex];
    const currentIndex = newUserInput.length - 1;

    // Check if correct
    if (newUserInput[currentIndex] !== gameState.sequence[currentIndex]) {
      // Wrong button!
      playSound('lose');

      const finalRound = gameState.round;
      if (finalRound > gameState.highScore) {
        saveHighScore('simonSays', finalRound);
      }

      setGameState(prev => ({
        ...prev,
        gameStatus: 'gameOver',
        userInput: newUserInput,
        highScore: Math.max(prev.highScore, finalRound)
      }));
      return;
    }

    // Correct so far
    setGameState(prev => ({ ...prev, userInput: newUserInput }));

    // Check if round complete
    if (newUserInput.length === gameState.sequence.length) {
      playSound('match');

      // Add new button to sequence
      setTimeout(() => {
        const newButton = Math.floor(Math.random() * 4);
        const newSequence = [...gameState.sequence, newButton];

        setGameState(prev => ({
          ...prev,
          sequence: newSequence,
          userInput: [],
          round: prev.round + 1,
          gameStatus: 'showing'
        }));

        showSequence(newSequence);
      }, 1000);
    }
  }, [gameState, playButtonTone, showSequence]);

  // Reset game
  const resetGame = useCallback(() => {
    showTimeoutsRef.current.forEach(clearTimeout);
    showTimeoutsRef.current = [];

    setGameState({
      sequence: [],
      userInput: [],
      round: 0,
      gameStatus: 'ready',
      speed: gameState.speed,
      highScore: getHighScore('simonSays'),
      showingIndex: -1
    });
  }, [gameState.speed]);

  // Set speed
  const setSpeed = useCallback((speed: Speed) => {
    setGameState(prev => ({ ...prev, speed }));
  }, []);

  // Cleanup — clear every tracked timeout on unmount
  useEffect(() => {
    return () => {
      showTimeoutsRef.current.forEach(clearTimeout);
      showTimeoutsRef.current = [];
    };
  }, []);

  return {
    gameState,
    startGame,
    handleButtonPress,
    resetGame,
    setSpeed
  };
};

/**
 * Memory Match Game Page
 * Main container for the Memory Match game
 */

import React, { useEffect } from 'react';
import { useMemoryMatch } from '../../../hooks/useMemoryMatch';
import GameLayout from '../../shared/GameLayout';
import GameBoard from './GameBoard';
import type { Difficulty, Theme } from './types';
import { difficultySettings, themeNames } from './themes';
import { formatTime, celebrateWin, getStatusColor } from '../../../utils/gameUtils';

interface MemoryMatchPageProps {
  onNavigateHome: () => void;
}

const MemoryMatchPage: React.FC<MemoryMatchPageProps> = ({ onNavigateHome }) => {
  const { gameState, handleCardClick, resetGame, setDifficulty, setTheme } = useMemoryMatch();

  const {
    moves,
    timer,
    bestTime,
    gameStatus,
    difficulty,
    theme,
    matchedPairs
  } = gameState;

  const totalPairs = difficultySettings[difficulty].pairs;
  const progress = (matchedPairs.size / totalPairs) * 100;

  // Celebrate on win
  useEffect(() => {
    if (gameStatus === 'completed') {
      celebrateWin();
    }
  }, [gameStatus]);

  const handleDifficultyChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    if (gameStatus !== 'playing') {
      setDifficulty(e.target.value as Difficulty);
    }
  };

  const handleThemeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    if (gameStatus !== 'playing') {
      setTheme(e.target.value as Theme);
    }
  };

  const getStatusMessage = (): string => {
    switch (gameStatus) {
      case 'ready':
        return '🎯 Click any card to start!';
      case 'playing':
        return '🧠 Find all the matching pairs!';
      case 'completed':
        return '🎉 You won! Congratulations!';
      default:
        return '';
    }
  };

  const headerActions = (
    <>
      {/* Difficulty Selector - Compact on mobile */}
      <select
        value={difficulty}
        onChange={handleDifficultyChange}
        disabled={gameStatus === 'playing'}
        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
        title="Game Difficulty"
      >
        {Object.entries(difficultySettings).map(([key, settings]) => (
          <option key={key} value={key}>
            {settings.name}
          </option>
        ))}
      </select>

      {/* Theme Selector - Compact on mobile */}
      <select
        value={theme}
        onChange={handleThemeChange}
        disabled={gameStatus === 'playing'}
        className="kid-input text-xs md:text-sm px-2 md:px-3 py-1 md:py-2"
        title="Card Theme"
      >
        {Object.entries(themeNames).map(([key, name]) => (
          <option key={key} value={key}>
            {name}
          </option>
        ))}
      </select>

      {/* New Game Button - Compact on mobile */}
      <button
        className="kid-button text-xs md:text-sm bg-blue-500 hover:bg-blue-600 px-2 md:px-4 py-1 md:py-2"
        onClick={resetGame}
      >
        <span className="md:hidden">🔄</span>
        <span className="hidden md:inline">🔄 New Game</span>
      </button>
    </>
  );

  return (
    <GameLayout
      title="Memory Match"
      emoji="🃏"
      onNavigateHome={onNavigateHome}
      headerActions={headerActions}
      bgColorClass="bg-gradient-to-b from-pink-100 to-purple-100"
    >
      {/* Stats Panel - Compact on mobile */}
      <div className="kid-card max-w-4xl mx-auto mb-2 md:mb-4 p-2 md:p-4">
        <div className="grid grid-cols-3 gap-2 md:gap-4">
          {/* Moves */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Moves</p>
            <p className="text-xl md:text-3xl font-bold text-blue-600">{moves}</p>
          </div>

          {/* Timer */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Time</p>
            <p className="text-xl md:text-3xl font-bold text-purple-600">
              {formatTime(timer)}
            </p>
          </div>

          {/* Best Time */}
          <div className="text-center">
            <p className="text-xs md:text-sm text-slate-600 font-semibold">Best</p>
            <p className="text-xl md:text-3xl font-bold text-yellow-600">
              {bestTime > 0 ? formatTime(bestTime) : '--:--'}
            </p>
          </div>
        </div>

        {/* Progress Bar - Smaller on mobile */}
        <div className="mt-2 md:mt-4">
          <div className="flex justify-between text-xs md:text-sm text-slate-600 mb-1">
            <span>Progress</span>
            <span>{matchedPairs.size} / {totalPairs}</span>
          </div>
          <div className="w-full bg-slate-200 rounded-full h-2 md:h-4 overflow-hidden">
            <div
              className="bg-gradient-to-r from-blue-500 to-purple-500 h-full transition-all duration-300 rounded-full"
              style={{ width: `${progress}%` }}
            />
          </div>
        </div>
      </div>

      {/* Status Message - Smaller on mobile */}
      <div className="text-center mb-2 md:mb-4">
        <p className={`text-sm md:text-lg font-semibold ${getStatusColor(gameStatus, { playing: 'text-purple-600' })}`}>
          {getStatusMessage()}
        </p>
      </div>

      {/* Game Board */}
      <div className="mb-2 md:mb-6">
        <GameBoard gameState={gameState} onCardClick={handleCardClick} />
      </div>

      {/* Instructions - Hidden on mobile, visible on larger screens */}
      <div className="kid-card max-w-4xl mx-auto hidden md:block">
        <h2 className="text-xl font-bold mb-3 text-center text-purple-800">
          How to Play
        </h2>

        <div className="space-y-3 text-slate-700">
          <div>
            <h3 className="font-semibold text-lg mb-1">🎯 Goal</h3>
            <p>
              Find all matching pairs of cards by remembering where each card is located!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">🎮 How to Play</h3>
            <ul className="list-disc list-inside space-y-1">
              <li>Click on a card to flip it over</li>
              <li>Click on a second card to see if they match</li>
              <li>If they match, they stay face up! ✓</li>
              <li>If they don't match, they flip back</li>
              <li>Try to find all pairs in the fewest moves!</li>
            </ul>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">⚙️ Settings</h3>
            <ul className="list-disc list-inside space-y-1">
              <li><strong>Easy:</strong> 6 pairs (4x3 grid)</li>
              <li><strong>Medium:</strong> 8 pairs (4x4 grid)</li>
              <li><strong>Hard:</strong> 12 pairs (4x6 grid)</li>
            </ul>
            <p className="mt-2 text-sm italic">
              Choose your favorite theme and challenge level before starting!
            </p>
          </div>

          <div>
            <h3 className="font-semibold text-lg mb-1">💡 Tips</h3>
            <ul className="list-disc list-inside space-y-1">
              <li>Pay attention to where each card is!</li>
              <li>Try to remember patterns</li>
              <li>The fewer moves, the better your score</li>
              <li>Beat your best time!</li>
            </ul>
          </div>
        </div>
      </div>

      {/* Completion Modal */}
      {gameStatus === 'completed' && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="kid-card max-w-md w-full text-center">
            <div className="text-6xl mb-4">🎉</div>
            <h2 className="text-3xl font-bold text-green-600 mb-4">
              You Won!
            </h2>

            <div className="mb-6 space-y-3">
              <div>
                <p className="text-lg text-slate-600">Total Moves</p>
                <p className="text-4xl font-bold text-blue-600">{moves}</p>
              </div>

              <div>
                <p className="text-lg text-slate-600">Time</p>
                <p className="text-4xl font-bold text-purple-600">
                  {formatTime(timer)}
                </p>
              </div>

              {timer === bestTime && bestTime > 0 && (
                <div className="bg-yellow-100 border-2 border-yellow-400 rounded-lg p-3">
                  <p className="text-lg text-yellow-800 font-semibold">
                    🏆 New Best Time! 🏆
                  </p>
                </div>
              )}
            </div>

            <div className="flex gap-3 justify-center">
              <button
                className="kid-button bg-purple-500 hover:bg-purple-600 text-lg"
                onClick={resetGame}
              >
                🔄 Play Again
              </button>
              <button
                className="kid-button bg-slate-500 hover:bg-slate-600 text-lg"
                onClick={onNavigateHome}
              >
                ← Home
              </button>
            </div>
          </div>
        </div>
      )}
    </GameLayout>
  );
};

export default MemoryMatchPage;

