58	            onNavigateToTetris={() => navigateTo('tetris')}
59	            onNavigateToJellyVolleyball={() => navigateTo('jellyvolleyball')}
60	            onNavigateToSnake={() => navigateTo('snake')}
61	            onNavigateToMemoryMatch={() => navigateTo('memoryMatch')}
62	            onNavigateToDrawingChallenge={() => navigateTo('drawingChallenge')}
63	            onNavigateToPopBalloons={() => navigateTo('popBalloons')}
64	            onNavigateToSimonSays={() => navigateTo('simonSays')}
65	            onNavigateToBubblePop={() => navigateTo('bubblePop')}
66	            onNavigateToColorMixer={() => navigateTo('colorMixer')}
67	            onNavigateToMathFacts={() => navigateTo('mathFacts')}
68	            onNavigateToShapeSorting={() => navigateTo('shapeSorting')}
